import { ref } from 'vue'
import { storageGet, storageSet } from '../utils/storage'

type Theme = 'light' | 'dark'
const KEY = 'memorize-words-theme'

/* 单例：主题（明亮 / 深邃） */
const theme = ref<Theme>(storageGet<Theme>(KEY, 'light') === 'dark' ? 'dark' : 'light')

export function useTheme() {
  function toggle(): void {
    theme.value = theme.value === 'light' ? 'dark' : 'light'
    storageSet(KEY, theme.value)
  }
  return { theme, toggle }
}
